#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    int total = 0;
    for (char c : s) total += c - '0';

    if (total == 0) {
        cout << (n >= 2 ? "YES\n" : "NO\n");
        return 0;
    }

    vector<bool> prefix(total + 1, false);
    int sum = 0;
    for (int i = 0; i + 1 < n; ++i) {
        sum += s[i] - '0';
        prefix[sum] = true;
    }

    for (int target = 1; target * 2 <= total; ++target) {
        if (total % target != 0) continue;

        bool valid = true;
        for (int boundary = target; boundary < total; boundary += target) {
            if (!prefix[boundary]) {
                valid = false;
                break;
            }
        }

        if (valid) {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

